script:
import time, json

SEL_BRANCH, SEL_PARTY, SEL_DAY, SEL_HOUR = "selectCoso", "selectSoNguoi", "selectDay", "selectHour"
OLD_BRANCH_ID = "68737cd823d94c3bb82bc42a"  # chi nhánh trong code cũ: Chao Xian Kim Mã
DAY_LABELS = {0: "Hôm nay", 1: "Ngày mai", 2: "Ngày kia"}
Q = json.dumps

def wait_until(expr, timeout=15.0):
    for _ in range(int(timeout / 0.1)):
        if js(f"(()=>!!({expr}))()"):
            return True
        time.sleep(0.1)
    return False

def options(sid):
    return js(f"(()=>[...document.getElementById({Q(sid)}).options].map(o=>[o.value,o.text.trim(),o.disabled]))()")

def js_set(sid, val):
    return js(f"""(()=>{{
        const s=document.getElementById({Q(sid)});
        s.value={Q(val)};
        s.dispatchEvent(new Event('input',{{bubbles:true}}));
        s.dispatchEvent(new Event('change',{{bubbles:true}}));
        return s.value;
    }})()""")

def pick(sid, match, label):
    hits = [o for o in options(sid) if match(o)]
    if not hits:
        raise RuntimeError(f"UNAVAILABLE: không có {label}")
    val, _, disabled = hits[0]
    if disabled:
        raise RuntimeError(f"UNAVAILABLE: {label} bị disabled")
    if js_set(sid, val) != val:
        raise RuntimeError(f"MISMATCH: {sid} không nhận giá trị {val}")
    return val

def wait_hours():
    prev, stable = None, 0
    for _ in range(150):
        opts = options(SEL_HOUR)
        stable = stable + 1 if (len(opts) > 1 and opts == prev) else 0
        prev = opts
        if stable >= 5:  # ổn định khoảng 0.5 giây
            return
        time.sleep(0.1)
    raise RuntimeError("UNAVAILABLE: danh sách giờ không tải ổn định")

def fill_text(sel, text):
    js(f"(()=>{{const e=document.querySelector({Q(sel)}); e.focus(); e.select(); return 1}})()")
    press_key('Backspace')
    type_text(text)
    time.sleep(0.2)

# 1. Chờ form xuất hiện
if not wait_until("document.getElementById('selectCoso') && document.getElementById('nameOrder')"):
    raise RuntimeError("FORM: không thấy form đặt bàn")

# 2. Chi nhánh, số người, ngày (trước khi chờ danh sách giờ)
if BRANCH is None:
    branch_match = lambda o: o[0] == OLD_BRANCH_ID
else:
    branch_match = lambda o: o[1] == BRANCH.strip()
branch_val = pick(SEL_BRANCH, branch_match, f"chi nhánh {BRANCH or OLD_BRANCH_ID}")

party_val = pick(SEL_PARTY, lambda o: o[1] == str(PARTY) or o[0] == str(PARTY), f"số người {PARTY}")

day_cands = {x for x in (DAY_LABELS.get(DAY_OFFSET), DATE_DMY, DATE_ISO) if x}
day_val = pick(SEL_DAY, lambda o: o[1] in day_cands or o[0] in day_cands, f"ngày offset {DAY_OFFSET}")

# 3. Chờ danh sách giờ ổn định rồi chọn giờ
time.sleep(0.3)
wait_hours()
hour_val = pick(SEL_HOUR, lambda o: o[1] == HHMM or o[0] in (HHMM, HHMM + ":00"), f"giờ {HHMM}")

# 4. Điền thông tin khách
has_email = js("""(()=>{
    const e=document.querySelector('input[type=email],input[id*=mail i],input[name*=mail i],input[placeholder*=mail i]');
    if(e) e.setAttribute('data-bot','email');
    return !!e;
})()""")
fill_text('#nameOrder', NAME)
fill_text('#sdtOrder', PHONE)
if has_email and EMAIL:
    fill_text('[data-bot=email]', EMAIL)

# 5. Đọc lại giá trị thật và so khớp
exp = {
    '#selectCoso': branch_val,
    '#selectSoNguoi': party_val,
    '#selectDay': day_val,
    '#selectHour': hour_val,
    '#nameOrder': NAME,
    '#sdtOrder': PHONE,
}
if has_email and EMAIL:
    exp['[data-bot=email]'] = EMAIL

got = js(f"(()=>{Q(list(exp))}.map(s=>[s,document.querySelector(s)?.value??null]))()")
bad = [(s, exp[s], v) for s, v in got if (v or '').strip() != str(exp[s]).strip()]
if bad:
    raise RuntimeError(f"MISMATCH: {bad}")

print("OK: đã điền form, chưa gửi:", {s: v for s, v in got})
